// Receives HOT / lead_qualified events fired by the CRM stage webhook.
// Only acts on genuine qualification events; everything else is dropped so this
// workflow can safely share the stage webhook feed.
// Mode: "Run Once for All Items".
const out = [];
for (const item of $input.all()) {
  const d = item.json.body || item.json;
  const event = d.event_type || '';
  const stage = d.stage || '';
  if (event !== 'lead_qualified' && stage !== 'qualified') continue;
  out.push({ json: {
    name: (d.name || 'HOT lead').trim(),
    email: (d.email || '').trim(),
    mobile: (d.mobile || '').trim(),
    location: (d.location || '').trim(),
    stageLabel: (d.stage_label || 'Qualified (HOT)').trim()
  } });
}
return out;
